\title{The Field with One Element Meets Tropical Geometry:\\
A Vertex-Counting Correspondence for Toric Varieties}
\author{Aristotle}
\date{2026-07-09}

\begin{document}

\begin{abstract}
The field with one element $\FF_1$ is a conjectural object introduced to explain
structural regularities in the Weil conjectures --- the way point counts of
varieties over finite fields with $q$ elements degenerate, as $q \to 1$, into
combinatorial invariants. Independently, tropical geometry replaces classical
arithmetic by the min-plus semiring $(\RR \cup \{\infty\}, \min, +)$, whose
defining feature is idempotent addition and the total absence of additive
inverses. We develop the thesis that these two circles of ideas are two faces of
one object: the tropical semiring \emph{is} the field with one element. An
$\FF_1$-variety is encoded by a lattice polytope $P$, its $\FF_1$-points are the
vertices of $P$, and its base change to $\ZZ$ is the associated toric variety
$X_P$. Our main result is a quantitative correspondence: for toric varieties
arising as products of projective spaces, the Euler characteristic of the base
change equals the number of $\FF_1$-points, $\chi(X_P) = \#\{\text{vertices of }
P\}$. The proof isolates two structural mechanisms --- vanishing of odd
cohomology and multiplicativity of total Betti numbers under products --- and
traces both to the idempotency that is the algebraic fingerprint of $\FF_1$. We
give complete statements, proof sketches, algorithms, and a program of
conjectural extensions to all smooth projective toric varieties.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Two ghosts}
Two evocative objects in modern algebra are conjectural in nature. The first is
the \emph{field with one element} $\FF_1$. Projective $n$-space over $\FF_q$ has
\[
|\PP^n(\FF_q)| = 1 + q + \cdots + q^n = \frac{q^{n+1}-1}{q-1}
\]
points; setting $q = 1$ formally yields $n+1$. Many counting formulas over
$\FF_q$ specialize at $q = 1$ to combinatorial quantities, and $\FF_1$ is the name
for whatever object makes these specializations literal. No field has one element,
since $0 \neq 1$ in a field; the task is to find a suitable category of
$\FF_1$-objects.

The second is \emph{tropical geometry}, the geometry of the min-plus semiring
\[
\TT = (\RR \cup \{\infty\},\ \oplus,\ \odot), \qquad
a \oplus b = \min(a,b), \quad a \odot b = a + b,
\]
with additive unit $\infty$ and multiplicative unit $0$. Its arithmetic is
idempotent, $a \oplus a = a$, and it has no additive inverses.

\subsection{The thesis}
The structural feature that makes $\FF_1$ impossible as a field is exactly the
feature the tropical semiring exhibits: an addition ($\min$) so degenerate it
admits no inverses. We treat $\TT$ as a concrete model of $\FF_1$ and study the
resulting geometry through polytopes and base change. A lattice polytope $P$
determines a projective toric variety $X_P$; we regard $P$ as the
tropical/$\FF_1$ datum and $X_P = P \otimes_{\FF_1} \ZZ$ as its base change to
$\ZZ$. Two notions of size --- the vertex count of $P$ and the Euler
characteristic of $X_P$ --- then agree for a load-bearing class of examples.

\section{Definitions and setup}

\begin{definition}[Tropical semiring]
The \emph{tropical} (min-plus) semiring is $\TT = (\RR \cup \{\infty\}, \oplus,
\odot)$ with $a \oplus b = \min(a,b)$ and $a \odot b = a + b$.
\end{definition}

\begin{proposition}[Idempotency, no inverses]\label{prop:fingerprint}
For all $a \in \TT$, $a \oplus a = a$. For $a \neq \infty$ there is no $b$ with
$a \oplus b = \infty$; i.e.\ $\TT$ has no additive inverses.
\end{proposition}
\begin{proof}
$\min(a,a) = a$ is immediate, and $\min(a,b) = \infty$ forces $a = b = \infty$.
\end{proof}

We take Proposition~\ref{prop:fingerprint} as the defining \emph{fingerprint of}
$\FF_1$. Every sign-free phenomenon below descends from it.

\begin{definition}[Lattice polytope, $\FF_1$-points]
A \emph{lattice polytope} $P \subset \RR^n$ is the convex hull of finitely many
points of $\ZZ^n$; its vertices $V(P)$ are its extreme points. The
\emph{$\FF_1$-points} of the tropical variety attached to $P$ are $V(P)$, and the
\emph{$\FF_1$-cardinality} is $\#V(P)$.
\end{definition}

\begin{definition}[Standard simplex]
The \emph{standard $n$-simplex} is $\Delta^n = \conv\{0, e_1, \dots, e_n\}$; it
has $\#V(\Delta^n) = n+1$ vertices.
\end{definition}

\begin{definition}[Product polytope]
For $P \subset \RR^m$, $Q \subset \RR^n$, the product is $P \times Q = \{(x,y):
x \in P,\ y \in Q\} \subset \RR^{m+n}$.
\end{definition}

\begin{lemma}[Vertices multiply]\label{lem:vertmult}
$V(P \times Q) = V(P) \times V(Q)$, so $\#V(P \times Q) = \#V(P) \cdot \#V(Q)$.
\end{lemma}
\begin{proof}
Supporting functionals on $P \times Q$ split as $(\xi,\eta) \mapsto \xi(x) +
\eta(y)$; a point maximizes a generic functional iff each coordinate maximizes the
corresponding factor functional. Hence extreme points of the product are pairs of
extreme points of the factors.
\end{proof}

\begin{definition}[Toric variety; base change]
A full-dimensional lattice polytope $P$ determines a projective toric variety
$X_P$ via its normal fan. We regard $P \rightsquigarrow X_P$ as base change to
$\ZZ$, written $X_P = P \otimes_{\FF_1} \ZZ$.
\end{definition}

\begin{fact}[Simplex to projective space; products]\label{fact:base}
$X_{\Delta^n} = \PP^n$, and $X_{P \times Q} = X_P \times X_Q$. In particular
$X_{\Delta^{n_1} \times \cdots \times \Delta^{n_k}} = \PP^{n_1} \times \cdots
\times \PP^{n_k}$.
\end{fact}

\begin{definition}[Topological invariants]
For a compact complex variety $X$ let $b_i(X) = \dim_\QQ H^i(X;\QQ)$. The
\emph{Poincar\'e polynomial} is $P_X(t) = \sum_i b_i(X) t^i$, the \emph{total
Betti number} is $B(X) = P_X(1)$, and the \emph{Euler characteristic} is
$\chi(X) = \sum_i (-1)^i b_i(X) = P_X(-1)$.
\end{definition}

\begin{fact}[Cohomology of projective space]\label{fact:proj}
$H^\ast(\PP^n;\QQ)$ has $b_{2i} = 1$ for $0 \le i \le n$ and vanishing odd Betti
numbers; hence $P_{\PP^n}(t) = 1 + t^2 + \cdots + t^{2n}$ and $\chi(\PP^n) = n+1 =
\#V(\Delta^n)$.
\end{fact}

\section{The Vertex--Euler Correspondence}

\begin{lemma}[No-odd-cohomology collapse]\label{lem:collapse}
If $b_i(X) = 0$ for all odd $i$, then $\chi(X) = B(X) = \sum_i b_i(X)$.
\end{lemma}
\begin{proof}
$\chi(X) = P_X(-1) = \sum_i (-1)^i b_i(X)$; if the odd $b_i$ vanish, every term
has $(-1)^i = +1$, so $P_X(-1) = P_X(1) = B(X)$.
\end{proof}

\begin{lemma}[Multiplicativity]\label{lem:mult}
For compact $X, Y$ with finite-dimensional rational cohomology, $P_{X\times Y}(t)
= P_X(t) P_Y(t)$; hence $\chi(X \times Y) = \chi(X)\chi(Y)$ and $B(X \times Y) =
B(X) B(Y)$. If $X$ and $Y$ have no odd cohomology, neither does $X \times Y$.
\end{lemma}
\begin{proof}
By the K\"unneth theorem over $\QQ$, $b_k(X\times Y) = \sum_{i+j=k} b_i(X)b_j(Y)$,
the coefficients of $P_X(t)P_Y(t)$. Evaluating at $t = \pm 1$ gives
multiplicativity of $B$ and $\chi$. If the odd Betti numbers of $X, Y$ vanish, a
nonzero term of $b_k$ needs $i,j$ even, forcing $k$ even.
\end{proof}

\begin{theorem}[Vertex--Euler Correspondence]\label{thm:main}
Let $P = \Delta^{n_1} \times \cdots \times \Delta^{n_k}$ and $X_P = \PP^{n_1}
\times \cdots \times \PP^{n_k}$. Then $X_P$ has no odd cohomology and
\[
\chi(X_P) = \prod_{j=1}^{k}(n_j + 1) = \#V(P) = \#\FF_1\text{-points}(P).
\]
Moreover $B(X_P) = \chi(X_P) = \#V(P)$.
\end{theorem}
\begin{proof}
Each $\PP^{n_j}$ has no odd cohomology and $\chi(\PP^{n_j}) = n_j + 1$
(Fact~\ref{fact:proj}). By Lemma~\ref{lem:mult}, $X_P$ has no odd cohomology and
$\chi(X_P) = \prod_j (n_j+1)$. By Lemma~\ref{lem:vertmult}, $\#V(P) = \prod_j
(n_j+1)$. The two products agree, and Lemma~\ref{lem:collapse} gives $B(X_P) =
\chi(X_P)$.
\end{proof}

\begin{remark}
The equality $\chi = B$ is the concrete shadow of
Proposition~\ref{prop:fingerprint}: the a priori signed Euler characteristic
collapses to an unsigned count because there is no odd cohomology to cancel --- the
topological echo of ``no additive inverses.''
\end{remark}

\section{Refinement: the Poincar\'e polynomial}

\begin{proposition}[Graded correspondence]\label{prop:graded}
With $P, X_P$ as in Theorem~\ref{thm:main},
\[
P_{X_P}(t) = \prod_{j=1}^{k}\bigl(1 + t^2 + \cdots + t^{2 n_j}\bigr)
= \prod_{j=1}^{k}\frac{t^{2(n_j+1)} - 1}{t^2 - 1},
\]
a polynomial in $t^2$ with nonnegative coefficients summing to $\#V(P)$.
\end{proposition}
\begin{proof}
Immediate from Fact~\ref{fact:proj} and Lemma~\ref{lem:mult}; set $t=1$ to recover
Theorem~\ref{thm:main}.
\end{proof}

The coefficients of $P_{X_P}(t)$ are the even Betti numbers of $X_P$ and form the
symmetric $h$-vector of $P$. Symmetry (Dehn--Sommerville) is Poincar\'e duality of
$X_P$.

\section{Algorithms}
\textbf{Algorithm A} (vertex count): return $\prod_j (n_j+1)$, in $O(k)$
multiplications. \textbf{Algorithm B} (Poincar\'e polynomial): convolve the factor
lists $[1,0,1,\dots,1]$ of length $2n_j+1$; the coefficient sum is $B$, the
alternating sum is $\chi$. \textbf{Algorithm C} (check): assert vertex count,
Euler characteristic, and total Betti number coincide and that odd coefficients
vanish.

\section{Numerical demonstrations}
For a large family of tuples one verifies $\chi(X_P) = \prod_j (n_j+1) = \#V(P)$,
vanishing of odd coefficients of $P_{X_P}(t)$, the identity $\chi = B$, and
palindromicity of the coefficient sequence (Poincar\'e duality). For example,
$\PP^2 \times \PP^1$ gives $P_{X_P}(t) = 1 + 2t^2 + 2t^4 + t^6$, so $\chi = B = 6
= 3 \cdot 2 = \#V(\Delta^2 \times \Delta^1)$.

\section{Discussion and future directions}

\begin{conjecture}[All smooth projective toric varieties]
For every smooth projective toric variety $X$, the Euler characteristic equals the
number of vertices of its moment polytope, equivalently the number of maximal
cones of the normal fan, equivalently the number of torus-fixed points.
\end{conjecture}
The Bia\l ynicki--Birula decomposition attaches one even-dimensional cell to each
torus-fixed point, so odd cohomology vanishes and Lemma~\ref{lem:collapse} applies.

\begin{conjecture}[$h$-vector / Poincar\'e polynomial]
For a simplicial polytope $P$ with normal fan defining $X$, the Poincar\'e
polynomial of $X$ is the generating function of the $h$-vector of $P$; at $1$ it
recovers the vertex count, and Dehn--Sommerville becomes Poincar\'e duality.
\end{conjecture}

\begin{conjecture}[Homomorphism property]
The $\FF_1$-cardinality is a semiring homomorphism from the min-plus world to the
counting semiring: multiplicative under products and inclusion--exclusion under
tropical unions, mirroring Euler characteristics.
\end{conjecture}

\section{Conclusion}
A polytope is an $\FF_1$-variety; its vertices are its $\FF_1$-points; its base
change to $\ZZ$ is a toric variety; and the tropical cardinality equals the Euler
characteristic of that variety across products of projective spaces, with the
graded refinement recording the full cohomology. Both the equality and its
sign-free character descend from idempotency --- the fingerprint that makes
$\FF_1$ tropical and tropical geometry the geometry of $\FF_1$.

\end{document}

