"""
Demo: the tropical (min-plus) semiring and its F_1 fingerprint.

Verifies numerically that tropical addition is idempotent (min(a,a)=a), that
infinity is the additive identity and 0 the multiplicative identity, and that no
finite element has an additive inverse -- the algebraic signature that ties the
tropical semiring to the field with one element.
"""
from __future__ import annotations
from math import inf
from typing import List


def tadd(a: float, b: float) -> float:
    return min(a, b)


def tmul(a: float, b: float) -> float:
    return a + b


def idempotent(sample: List[float]) -> bool:
    return all(tadd(a, a) == a for a in sample)


def additive_identity(sample: List[float]) -> bool:
    return all(tadd(a, inf) == a for a in sample)


def multiplicative_identity(sample: List[float]) -> bool:
    return all(tmul(a, 0.0) == a for a in sample)


def has_no_additive_inverse(sample: List[float]) -> bool:
    # a has an inverse b iff tadd(a,b)=inf; impossible unless a=inf.
    def has_inverse(a: float) -> bool:
        return any(tadd(a, b) == inf for b in sample + [inf])
    return all(not has_inverse(a) for a in sample if a != inf)


def main() -> None:
    sample = [-3.0, -1.0, 0.0, 2.5, 7.0]
    print("idempotent (min a a = a):        ", idempotent(sample))
    print("additive identity is +inf:       ", additive_identity(sample))
    print("multiplicative identity is 0:    ", multiplicative_identity(sample))
    print("no finite additive inverse:      ", has_no_additive_inverse(sample))
    print()
    print("This defect -- addition with no inverse -- is the fingerprint of F_1.")


if __name__ == "__main__":
    main()

