function VERTEX_COUNT(dims = [n_1, ..., n_k]):
    total <- 1
    for n in dims:
        total <- total * (n + 1)   # n-simplex has n+1 vertices
    return total

function POINCARE(dims):
    coeffs <- [1]                      # Poincare polynomial of a point
    for n in dims:
        factor <- [1,0,1,0,...,1]      # length 2n+1, ones at even indices
        coeffs <- CONVOLVE(coeffs, factor)
    return coeffs

function CONVOLVE(a, b):
    r <- array of zeros of length len(a)+len(b)-1
    for i, ai in a:
        for j, bj in b:
            r[i+j] <- r[i+j] + ai*bj
    return r

