from __future__ import annotations
from typing import List, Sequence


def proj_poincare(n: int) -> List[int]:
    c = [0] * (2 * n + 1)
    for i in range(n + 1):
        c[2 * i] = 1
    return c


def convolve(a: List[int], b: List[int]) -> List[int]:
    r = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            r[i + j] += ai * bj
    return r


def poincare_polynomial(dims: Sequence[int]) -> List[int]:
    coeffs: List[int] = [1]
    for n in dims:
        coeffs = convolve(coeffs, proj_poincare(n))
    return coeffs
